/* eslint-disable */
/* global WebImporter */
/**
 * Parser for columns-article-rail. Base: columns.
 * Source: komatsu.com article pages (article template)
 * Instance selector: #articleLeft .articledetail_contents
 * Structure (DA block table, 2 columns):
 *   one row per author: [ photo | name, role, email (mailto link), phone (tel link) ]
 * Not authored: date + tags (page metadata via komatsu-article-metadata transformer)
 *   and the save/share buttons (generated by the block).
 * Iteration: keyed on li.articledetail_contact (one per author contact).
 * Generated: 2026-10-12
 */
export default function parse(element, { document }) {
  let contacts = Array.from(element.querySelectorAll('li.articledetail_contact'));
  if (!contacts.length) {
    // Fallback: any list item that carries a details wrapper or a mailto/tel link
    contacts = Array.from(element.querySelectorAll('li')).filter(
      (li) => li.querySelector('.details, a[href^="mailto:"], a[href^="tel:"]'),
    );
  }

  const makeText = (text) => {
    const p = document.createElement('p');
    p.textContent = text;
    return p;
  };
  const makeLink = (href, text) => {
    const p = document.createElement('p');
    const a = document.createElement('a');
    a.href = href;
    a.textContent = text;
    p.appendChild(a);
    return p;
  };
  const clean = (el) => (el ? el.textContent.replace(/\s+/g, ' ').trim() : '');

  const cells = [];

  contacts.forEach((contact) => {
    const photo = contact.querySelector('img.profile, picture') || contact.querySelector(':scope > img');
    const details = contact.querySelector('.details') || contact;

    const name = clean(details.querySelector('.name'));
    const role = clean(details.querySelector('.role'));
    const mail = details.querySelector('.mail a[href^="mailto:"]') || details.querySelector('a[href^="mailto:"]');
    const phone = details.querySelector('.contact_number a[href^="tel:"]') || details.querySelector('a[href^="tel:"]');

    const detailCell = [];
    if (name) detailCell.push(makeText(name));
    if (role) detailCell.push(makeText(role));
    if (mail) detailCell.push(makeLink(mail.getAttribute('href'), clean(mail)));
    if (phone) detailCell.push(makeLink(phone.getAttribute('href'), clean(phone)));

    if (!detailCell.length && !photo) return;
    cells.push([photo || '', detailCell.length ? detailCell : '']);
  });

  if (!cells.length) {
    // No author contact: date/tags/share are not authored, so drop the rail content
    element.remove();
    return;
  }

  const block = WebImporter.Blocks.createBlock(document, { name: 'columns-article-rail', cells });
  element.replaceWith(block);
}
